const rows = $input.all().map(i => i.json);
if (rows.length === 0) throw new Error('Нет ответов с расшифровкой');

const parts = [];
for (const r of rows) {
  let block = '[answer_id=' + r.answer_id + ']\n';
  block += 'Компетенция: ' + (r.competency_name || '-') + '\n';
  block += 'Вопрос: ' + r.question_text + '\n';
  block += 'Эталон: ' + (r.reference_answer || '-') + '\n';
  if (r.dev_indicators) block += 'Признаки слабого ответа: ' + r.dev_indicators + '\n';
  block += 'Ответ кандидата: ' + r.transcript + '\n';
  parts.push(block);
}

return [{ json: {
  session_id: rows[0].session_id,
  count:      rows.length,
  material:   parts.join('\n---\n'),
  rows:       rows
}}];

const meta = $('2. Собрать промпт').first().json;
const valid = new Set();
for (const r of meta.rows) valid.add(Number(r.answer_id));

const compById = {};
for (const r of meta.rows) compById[r.answer_id] = r.competency_id;

const out = [];

function push(o) {
  if (!o) return;
  const id = Number(o.answer_id);
  if (!valid.has(id)) return;
  let ku = parseInt(o.ku_level, 10);
  if (isNaN(ku)) ku = 1;
  if (ku < 1) ku = 1;
  if (ku > 5) ku = 5;
  out.push({
    answer_id:     id,
    competency_id: compById[id] || null,
    ku_level:      ku,
    rationale:     String(o.rationale || '').trim(),
    model:         'llama3.2:3b'
  });
}

function eat(v, depth) {
  if (v === null) return;
  if (v === undefined) return;
  if (depth > 5) return;
  if (Array.isArray(v)) { for (const x of v) eat(x, depth + 1); return; }
  if (typeof v === 'string') {
    let frag = null;
    const a = v.indexOf('['); const b = v.lastIndexOf(']');
    if (a !== -1) { if (b > a) frag = v.slice(a, b + 1); }
    if (frag === null) {
      const c = v.indexOf('{'); const d = v.lastIndexOf('}');
      if (c !== -1) { if (d > c) frag = v.slice(c, d + 1); }
    }
    if (frag === null) return;
    try { eat(JSON.parse(frag), depth + 1); }
    catch (e1) {
      try { eat(JSON.parse(frag.replace(/,\s*([}\]])/g, '$1')), depth + 1); }
      catch (e2) { return; }
    }
    return;
  }
  if (typeof v === 'object') {
    if (v.ku_level !== undefined && v.answer_id !== undefined) { push(v); return; }
    for (const x of Object.values(v)) eat(x, depth + 1);
  }
}

for (const item of $input.all()) eat(item.json, 0);

// не оценённые моделью — ставим 1, чтобы отчёт не был дырявым
const done = new Set(out.map(o => o.answer_id));
for (const r of meta.rows) {
  if (!done.has(Number(r.answer_id))) {
    out.push({
      answer_id: Number(r.answer_id), competency_id: r.competency_id,
      ku_level: 1, rationale: 'Модель не вернула оценку', model: 'llama3.2:3b'
    });
  }
}

return [{ json: { session_id: meta.session_id, scores: out, count: out.length } }];
